export function designMessage(text, language) {
  if (language === "en") return text;
  if (language !== "vi") throw new Error("Unsupported DESIGN language: " + language);
  if (!Object.hasOwn(vietnamese, text)) throw new Error("Untranslated DESIGN prose: " + text);
  return vietnamese[text];
}
